import{d as c,C as t,o as u,c as b,j as a,a as o,E as r,a3 as m}from"./chunks/framework.Q4yG9rk_.js";const _=JSON.parse('{"title":"道德经第十三章","description":"从宠辱若惊、有身与无身，读到不以荣患损身而可托天下。","frontmatter":{"title":"道德经第十三章","description":"从宠辱若惊、有身与无身，读到不以荣患损身而可托天下。","category":"guide","aliases":["道德经第十三章","老子第十三章","dao de jing chapter 13"],"source":["王弼《道德真经注》卷一"]},"headers":[],"relativePath":"daoism/dao-de-jing/chapter-13.md","filePath":"daoism/dao-de-jing/chapter-13.md","lastUpdated":1794189804000}'),p={name:"daoism/dao-de-jing/chapter-13.md"},y=c({...p,setup(g){const s=[{id:"favour-and-great-trouble",label:"宠辱若惊，贵大患若身",showLabel:!0,sentences:[[{text:"宠辱",glossary:"chongru"},"若",{text:"惊",glossary:"jing"},"，",{text:"贵",glossary:"gui"},{text:"大患",glossary:"dahuan"},"若身。"]],note:["【白话】得宠与受辱都让人惊惧不安；把重大忧患看得如自身一样重大。开头并列两个需要解释的说法，下文分别用何谓追问其含义。","【王弼注择要】「宠必有辱，荣必有患。」关于大患，注又说「大患，荣宠之属也」。王弼把荣宠带来的患难连进来，不把受宠看成可以永远安稳占有的好处。","【读法】贵大患若身语意有分歧。本页先保留其直译，再据王弼把注意力引向荣宠与自身的关系，不把贵解释成喜爱灾祸。"]},{id:"dependent-on-favour",label:"得之若惊，失之若惊",showLabel:!0,sentences:[["何谓宠辱若惊？宠为下，得之若惊，失之若惊，是谓宠辱若惊。"]],note:["【白话】什么叫得宠受辱都惊惧？得宠本已把自己放在受人支配的下位：得到它怕不能保住，失去它又惊恐不安，这就是宠辱若惊。","【读法】本页将宠为下理解为求宠、受宠者处于依附地位；这是一种解释取径。若把自身安定全系在他人的赐予上，得与失就都可能成为扰动，而不是只有失宠才会惊。"]},{id:"body-and-self-attachment",label:"吾所以有大患者，为吾有身",showLabel:!0,sentences:[["何谓贵大患若身？吾所以有大患者，为吾",{text:"有身",glossary:"youshen"},"；"],["及吾",{text:"无身",glossary:"wushen"},"，吾有何患？"]],note:["【白话】什么叫把大患看得如自身一样重大？我之所以有重大忧患，是因为我有此身，并将自身利害系在所追逐的荣宠上；若不再这样执持一己，还有什么同样的忧患呢？后半依王弼归于自然的解释来读。","【王弼注择要】「人迷之于荣宠，返之于身。」解释无身时，注说「归之自然也」。注从迷于荣宠转回自身，再由执身的牵累转向自然。","【读法】有身的字面是有此身体、自身；不将其简单改成身体有罪。无身循古注作不执持自我来理解，不作取消身体或轻弃生命解，也不是承诺一切现实风险从此消失。"]},{id:"entrusting-the-world",label:"贵以身为天下，若可寄天下",showLabel:!0,sentences:[["故贵以身为天下，若可",{text:"寄",glossary:"ji"},"天下；"],["爱以身为天下，若可",{text:"托",glossary:"tuo"},"天下。"]],note:["【白话】所以，珍重自身、不肯以天下的权位来换它的人，才可以把天下寄托给他；爱惜自身、不让外物损伤它的人，才可以把天下托付给他。此处循王弼的解释串讲。","【王弼注择要】「无以易其身，故曰贵也。」「无物可以损其身，故曰爱也。」结注说「不以宠辱荣患损易其身，然后乃可以天下付之也」。","【读法】贵身、爱身在本章不是争取更大私利，而是不为荣宠与患失轻易改变、损伤自身。王弼把这种不受宠辱摆布的自处能力，连到能否承担天下的责任。"]}],n=[{id:"chongru",term:"宠辱",sense:1},{id:"jing",term:"惊",sense:1},{id:"gui",term:"贵",sense:1,context:"贵大患若身中作看重解；篇末循王弼解释珍重自身。"},{id:"dahuan",term:"大患",sense:1},{id:"youshen",term:"有身",sense:1},{id:"wushen",term:"无身",sense:1},{id:"ji",term:"寄",sense:1},{id:"tuo",term:"托",sense:1}];return(x,e)=>{const i=t("DaoReadingPrelude"),l=t("DaoTextReading"),d=t("DaoLineGuide"),h=t("DaoKeywordCards");return u(),b("div",null,[e[0]||(e[0]=a("h1",{id:"道德经第十三章",tabindex:"-1"},[o("道德经第十三章 "),a("a",{class:"header-anchor",href:"#道德经第十三章","aria-label":'Permalink to "道德经第十三章"'},"​")],-1)),r(i,{title:"得宠为何也会惊，贵身为何能托天下？",summary:"本章先提出宠辱与身的两重难题，再分别解释，最后转到承担天下。阅读时要把无身与贵身放在一起看：不执一己，并没有取消对生命与责任的珍重。",points:[{label:"先读",text:"得到与失去宠爱，为什么都可能使人不安？"},{label:"再辨",text:"无身与贵身各自要松开、保全什么？"},{label:"后想",text:"不被荣宠摆布，怎样关联公共责任？"}],hint:"竹简模式先通读；经典阅读可展开段释义、点击标记字词查义。"}),e[1]||(e[1]=a("h2",{id:"【原典层】原文与段级释义",tabindex:"-1"},[o("【原典层】原文与段级释义 "),a("a",{class:"header-anchor",href:"#【原典层】原文与段级释义","aria-label":'Permalink to "【原典层】原文与段级释义"'},"​")],-1)),r(l,{sections:s,glossary:n,tone:"ink",density:"comfortable","aria-label":"《道德经》第十三章原文"}),e[2]||(e[2]=a("h2",{id:"【导读层】核心句引读",tabindex:"-1"},[o("【导读层】核心句引读 "),a("a",{class:"header-anchor",href:"#【导读层】核心句引读","aria-label":'Permalink to "【导读层】核心句引读"'},"​")],-1)),r(d,{lines:[{text:"得之若惊，失之若惊。",tone:"两面皆惊",guide:"若安定来自别人随时可收回的宠爱，得到也不会终结恐惧。这里追问依附关系，不是把所有认可与支持都判为有害。"},{text:"及吾无身，吾有何患？",tone:"辨身与执",guide:"依王弼归之自然的解释，无身关乎不被一己利害缠住。须连同篇末贵身、爱身读，不能孤立成贬弃生命的命令。"},{text:"爱以身为天下，若可托天下。",tone:"由己及任",guide:"结尾将自处推向承担。王弼重在不以宠辱荣患损易其身，并非说一个人只要自爱，就已经具备全部治理能力。"}]}),e[3]||(e[3]=a("h2",{id:"【注释层】字词释义",tabindex:"-1"},[o("【注释层】字词释义 "),a("a",{class:"header-anchor",href:"#【注释层】字词释义","aria-label":'Permalink to "【注释层】字词释义"'},"​")],-1)),r(h,{items:n}),e[4]||(e[4]=m("",15))])}}});export{_ as __pageData,y as default};
